import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };

test('submit validation and unknown jobs', async () => {
  const h = await createHost();
  for (const m of [0, 4, 5, -1, 2.5]) assert.equal((await h.submit('x', m)).ok, false, `max ${m}`);
  assert.equal(await h.job('x'), null);
  assert.equal((await h.claim('nope')).ok, false);
  assert.equal((await h.cancel('nope')).ok, false);
  assert.deepEqual(await h.submit('a', 2), ok);
  assert.equal((await h.submit('a', 1)).ok, false);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
});

test('retries until failed', async () => {
  const h = await createHost();
  await h.submit('a', 2);
  assert.deepEqual(await h.claim('a'), ok);
  assert.equal((await h.claim('a')).ok, false);
  assert.deepEqual(await h.fail('a'), ok);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 1, maxTries: 2 });
  await h.claim('a');
  assert.deepEqual(await h.lost('a'), ok);
  assert.deepEqual(await h.job('a'), { status: 'failed', tries: 2, maxTries: 2 });
  assert.equal((await h.claim('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
});

test('cancellation', async () => {
  const h = await createHost();
  await h.submit('q', 1);
  assert.deepEqual(await h.cancel('q'), ok);
  assert.equal((await h.job('q'))!.status, 'cancelled');
  assert.equal((await h.succeed('q')).ok, false);
  await h.submit('r', 3);
  await h.claim('r');
  assert.deepEqual(await h.cancel('r'), ok);
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.job('r'))!.status, 'cancelling');
  assert.deepEqual(await h.succeed('r'), ok);
  assert.deepEqual(await h.job('r'), { status: 'succeeded', tries: 1, maxTries: 3 });
  await h.submit('s', 3);
  await h.claim('s');
  await h.cancel('s');
  assert.deepEqual(await h.lost('s'), ok);
  assert.deepEqual(await h.job('s'), { status: 'cancelled', tries: 1, maxTries: 3 });
});

